import { loader } from 'fumadocs-core/source';
import { applyMdxPreset } from 'fumadocs-mdx/config';
import { defineDocs } from 'fumadocs-mdx/macro';
import { metaSchema, pageSchema } from 'fumadocs-core/source/schema';
import { quietDark, quietLight } from './code-themes';

// Every page is MDX. The reference pages (playbooks, skills, principles) are
// generated by scripts/sync-content.mjs from the repo and content/tldr.json.
const docs = defineDocs({
  dir: 'content/docs',
  docs: {
    schema: pageSchema,
    mdxOptions: applyMdxPreset({
      rehypeCodeOptions: {
        themes: { light: quietLight, dark: quietDark },
      },
    }),
  },
  meta: { schema: metaSchema },
});

export const source = loader({
  baseUrl: '/',
  source: docs.toFumadocsSource(),
});
